  final String entityId;
  final int version;
  final String changedAt;
  const SyncOutboxData({
    required this.entity,
    required this.entityId,
    required this.version,
    required this.changedAt,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['entity'] = Variable<String>(entity);
    map['entity_id'] = Variable<String>(entityId);
    map['version'] = Variable<int>(version);
    map['changed_at'] = Variable<String>(changedAt);
    return map;
  }

  SyncOutboxCompanion toCompanion(bool nullToAbsent) {
    return SyncOutboxCompanion(
      entity: Value(entity),
      entityId: Value(entityId),
      version: Value(version),
      changedAt: Value(changedAt),
    );
  }

  factory SyncOutboxData.fromJson(
    Map<String, dynamic> json, {
    ValueSerializer? serializer,
  }) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return SyncOutboxData(
      entity: serializer.fromJson<String>(json['entity']),
      entityId: serializer.fromJson<String>(json['entityId']),
      version: serializer.fromJson<int>(json['version']),
      changedAt: serializer.fromJson<String>(json['changedAt']),
    );
  }
  @override
  Map<String, dynamic> toJson({ValueSerializer? serializer}) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return <String, dynamic>{
      'entity': serializer.toJson<String>(entity),
      'entityId': serializer.toJson<String>(entityId),
      'version': serializer.toJson<int>(version),
      'changedAt': serializer.toJson<String>(changedAt),
    };
  }

  SyncOutboxData copyWith({
    String? entity,
    String? entityId,
    int? version,
    String? changedAt,
  }) => SyncOutboxData(
    entity: entity ?? this.entity,
    entityId: entityId ?? this.entityId,
    version: version ?? this.version,
    changedAt: changedAt ?? this.changedAt,
  );
  SyncOutboxData copyWithCompanion(SyncOutboxCompanion data) {
    return SyncOutboxData(
      entity: data.entity.present ? data.entity.value : this.entity,
      entityId: data.entityId.present ? data.entityId.value : this.entityId,
      version: data.version.present ? data.version.value : this.version,
      changedAt: data.changedAt.present ? data.changedAt.value : this.changedAt,
    );
  }

  @override
  String toString() {
    return (StringBuffer('SyncOutboxData(')
          ..write('entity: $entity, ')
          ..write('entityId: $entityId, ')
          ..write('version: $version, ')
          ..write('changedAt: $changedAt')
          ..write(')'))
        .toString();
  }

  @override
  int get hashCode => Object.hash(entity, entityId, version, changedAt);
  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      (other is SyncOutboxData &&
          other.entity == this.entity &&
          other.entityId == this.entityId &&
          other.version == this.version &&
          other.changedAt == this.changedAt);
}

class SyncOutboxCompanion extends UpdateCompanion<SyncOutboxData> {
  final Value<String> entity;
  final Value<String> entityId;
  final Value<int> version;
  final Value<String> changedAt;
  final Value<int> rowid;
  const SyncOutboxCompanion({
    this.entity = const Value.absent(),
    this.entityId = const Value.absent(),
    this.version = const Value.absent(),
    this.changedAt = const Value.absent(),
    this.rowid = const Value.absent(),
  });
  SyncOutboxCompanion.insert({
    required String entity,
    required String entityId,
    this.version = const Value.absent(),
    required String changedAt,
    this.rowid = const Value.absent(),
  }) : entity = Value(entity),
       entityId = Value(entityId),
       changedAt = Value(changedAt);
  static Insertable<SyncOutboxData> custom({
    Expression<String>? entity,
    Expression<String>? entityId,
    Expression<int>? version,
    Expression<String>? changedAt,
    Expression<int>? rowid,
  }) {
    return RawValuesInsertable({
      if (entity != null) 'entity': entity,
      if (entityId != null) 'entity_id': entityId,
      if (version != null) 'version': version,
      if (changedAt != null) 'changed_at': changedAt,
      if (rowid != null) 'rowid': rowid,
    });
  }

  SyncOutboxCompanion copyWith({
    Value<String>? entity,
    Value<String>? entityId,
    Value<int>? version,
    Value<String>? changedAt,
    Value<int>? rowid,
  }) {
    return SyncOutboxCompanion(
      entity: entity ?? this.entity,
      entityId: entityId ?? this.entityId,
      version: version ?? this.version,
      changedAt: changedAt ?? this.changedAt,
      rowid: rowid ?? this.rowid,
    );
  }

  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    if (entity.present) {
      map['entity'] = Variable<String>(entity.value);
    }
    if (entityId.present) {
      map['entity_id'] = Variable<String>(entityId.value);
    }
    if (version.present) {
      map['version'] = Variable<int>(version.value);
    }
    if (changedAt.present) {
      map['changed_at'] = Variable<String>(changedAt.value);
    }
    if (rowid.present) {
      map['rowid'] = Variable<int>(rowid.value);
    }
    return map;
  }

  @override
  String toString() {
    return (StringBuffer('SyncOutboxCompanion(')
          ..write('entity: $entity, ')
          ..write('entityId: $entityId, ')
          ..write('version: $version, ')
          ..write('changedAt: $changedAt, ')
          ..write('rowid: $rowid')
          ..write(')'))
        .toString();
  }
}

class DatabaseAtV6 extends GeneratedDatabase {
  DatabaseAtV6(QueryExecutor e) : super(e);
  late final Concepts concepts = Concepts(this);
  late final AppSettings appSettings = AppSettings(this);
  late final StudyProfiles studyProfiles = StudyProfiles(this);
  late final PendingAnswers pendingAnswers = PendingAnswers(this);
  late final RevisionCards revisionCards = RevisionCards(this);
  late final CardReviews cardReviews = CardReviews(this);
  late final SyncOutbox syncOutbox = SyncOutbox(this);
  late final Index cardReviewsSyncId = Index(
    'card_reviews_sync_id',
    'CREATE UNIQUE INDEX card_reviews_sync_id ON card_reviews (sync_id)',
  );
  @override
  Iterable<TableInfo<Table, Object?>> get allTables =>
      allSchemaEntities.whereType<TableInfo<Table, Object?>>();
  @override
  List<DatabaseSchemaEntity> get allSchemaEntities => [
    concepts,
    appSettings,
    studyProfiles,
    pendingAnswers,
    revisionCards,
    cardReviews,
    syncOutbox,
    cardReviewsSyncId,
  ];
  @override
  StreamQueryUpdateRules get streamUpdateRules => const StreamQueryUpdateRules([
    WritePropagation(
      on: TableUpdateQuery.onTableName(
        'concepts',
        limitUpdateKind: UpdateKind.delete,
      ),
      result: [TableUpdate('revision_cards', kind: UpdateKind.delete)],
    ),
    WritePropagation(
      on: TableUpdateQuery.onTableName(
        'revision_cards',
        limitUpdateKind: UpdateKind.delete,
      ),
      result: [TableUpdate('card_reviews', kind: UpdateKind.delete)],
    ),
  ]);
  @override
  int get schemaVersion => 6;
  @override
  DriftDatabaseOptions get options =>
      const DriftDatabaseOptions(storeDateTimeAsText: true);
}
